#include "fstr/parts_model.hpp"
#include "fstr/face_model.hpp"
#include "json.hpp"
#include <fstream>
#include <cmath>
#include <algorithm>
#include <filesystem>
#include <iostream>
int main(int argc,char**argv){try{if(argc!=11)throw std::invalid_argument("runtime sha skin face pose detector-dir width height rgba8 output-dir");fstr::PartsModel model(argv[1],argv[2],argv[3],argv[4],argv[5]);fstr::FaceModel detector(argv[6]);fstr::AnalysisImage image;image.width=std::stoi(argv[7]);image.height=std::stoi(argv[8]);if(image.width<1||image.height<1||image.width>2048||image.height>2048)throw std::invalid_argument("Input extent");image.rgba.resize(std::size_t(image.width)*std::size_t(image.height)*4);std::ifstream input(argv[9],std::ios::binary);input.read(reinterpret_cast<char*>(image.rgba.data()),std::streamsize(image.rgba.size()));if(!input||input.peek()!=EOF)throw std::runtime_error("Input length");std::filesystem::path output(argv[10]);if(!std::filesystem::create_directory(output))throw std::runtime_error("Output must be new directory");auto faces=detector.analyze(image);nlohmann::json rows=nlohmann::json::array();for(auto&f:faces){int x0=std::max(0,int(std::floor((f.box[0]+f.box[2])*.5-(f.box[2]-f.box[0])))),y0=std::max(0,int(std::floor((f.box[1]+f.box[3])*.5-(f.box[3]-f.box[1])))),x1=std::min(image.width,int(std::ceil((f.box[0]+f.box[2])*.5+(f.box[2]-f.box[0])))),y1=std::min(image.height,int(std::ceil((f.box[1]+f.box[3])*.5+(f.box[3]-f.box[1]))));fstr::AnalysisImage crop;crop.width=x1-x0;crop.height=y1-y0;crop.rgba.resize(std::size_t(crop.width)*std::size_t(crop.height)*4);for(int y=0;y<crop.height;++y)std::copy_n(image.rgba.data()+(std::size_t(y+y0)*std::size_t(image.width)+std::size_t(x0))*4,std::size_t(crop.width)*4,crop.rgba.data()+std::size_t(y)*std::size_t(crop.width)*4);auto mesh=model.face_mesh(crop);rows.push_back({{"box",f.box},{"score",f.score},{"scale_agreement",f.scale_agreement},{"crop",{x0,y0,x1,y1}},{"mesh",mesh}});}auto poses=model.people(image);for(std::size_t i=0;i<poses.size();++i){std::ofstream out(output/("pose-"+std::to_string(i)+".f32"),std::ios::binary);out.write(reinterpret_cast<const char*>(poses[i].data()),std::streamsize(poses[i].size()*4));if(!out)throw std::runtime_error("Output failed");}std::ofstream report(output/"result.json");report<<nlohmann::json{{"faces",rows},{"poses",poses.size()}}.dump(2);if(!report)throw std::runtime_error("Report failed");std::cout<<rows.size()<<" faces / "<<poses.size()<<" person masks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
